  // whitespaced env values) so middleware agrees with the rest of the app.
  if (isAuthBypass()) {
    if (isAuthUiPath(pathname)) {
      return withSecurityHeaders(
        NextResponse.redirect(new URL(`${BASE_PATH}/`, request.url)),
      );
    }
    return nextWithPath();
  }

