 * is a last-resort backstop; `refetchOnWindowFocus` covers tab-return recovery.
 */
export function getSessionArgs() {
  if (isAuthBypass()) {
    return {
      refetchInterval: 0,
      refetchOnWindowFocus: false,
      basePath: getBasePath(process.env.NEXT_PUBLIC_BASE_PATH || ""),
    };
  }

